INSERT INTO composition_translations(composition_id,locale,title,alternate_titles,summary,description,status) VALUES
('1fb530fb-1ef3-408b-976d-83e960a78032','zh-CN','《罗班与玛丽昂的游戏》','{}','亚当·德·拉·阿勒的music drama代表作，创作于1282年。','《罗班与玛丽昂的游戏》在本图集中连接亚当·德·拉·阿勒、阿拉斯、pastourelle、相关乐器与学习单元。扩展阶段将作品年代、来源与权利状态分开记录。','published'),
('1fb530fb-1ef3-408b-976d-83e960a78032','en','Le Jeu de Robin et de Marion','{}','A representative music drama by Adam de la Halle, composed in 1282.','Le Jeu de Robin et de Marion connects Adam de la Halle, Arras, its pastourelle, instruments, and learning units. The expansion keeps dates, sources, and rights status as separate evidence fields.','published'),
('821db903-82eb-4e68-8d6b-93064fbb729a','zh-CN','《亚当的游戏》','{}','亚当·德·拉·阿勒的music drama代表作，创作于1276年。','《亚当的游戏》在本图集中连接亚当·德·拉·阿勒、阿拉斯、liturgical play、相关乐器与学习单元。扩展阶段将作品年代、来源与权利状态分开记录。','published'),
('821db903-82eb-4e68-8d6b-93064fbb729a','en','Le Jeu d''Adam','{}','A representative music drama by Adam de la Halle, composed in 1276.','Le Jeu d''Adam connects Adam de la Halle, Arras, its liturgical play, instruments, and learning units. The expansion keeps dates, sources, and rights status as separate evidence fields.','published'),
('5691122b-5ac4-4d36-8461-e14905ff0aad','zh-CN','《并非献给他的爱人》','{}','雅各布·达·博洛尼亚的secular song代表作，创作于1350年。','《并非献给他的爱人》在本图集中连接雅各布·达·博洛尼亚、博洛尼亚、madrigal、相关乐器与学习单元。扩展阶段将作品年代、来源与权利状态分开记录。','published'),
