INSERT INTO music_learning_unit_translations(unit_id,locale,title,summary,objective,status) VALUES
('fc0fe935-da18-4424-a86f-af862f8e2e46','zh-CN','中世纪世俗歌曲：从戏剧到旋律','以《罗班与玛丽昂的游戏》和雅各布的牧歌为入口，辨认节奏、语言与表演场景。','能说出世俗歌曲与礼仪音乐在功能和听感上的两个差异。','published'),
('fc0fe935-da18-4424-a86f-af862f8e2e46','en','Medieval vernacular song: from drama to melody','Use Le Jeu de Robin et de Marion and Jacopo''s madrigals to identify rhythm, language, and performance setting.','Name two functional and listening differences between secular song and liturgical music.','published'),
('7ffd0691-ac3f-4eaa-8cfc-e0fc58a63929','zh-CN','新艺术的节奏组织','通过雅各布和迪费的片段比较等时结构、复调层次与乐句呼吸。','在乐谱上标出两个重复或变化的节奏手势。','published'),
('7ffd0691-ac3f-4eaa-8cfc-e0fc58a63929','en','Ars nova rhythmic organization','Compare Jacopo and Dufay excerpts to trace isorhythmic structure, polyphonic layers, and phrase breathing.','Mark two repeated or transformed rhythmic gestures in the score.','published'),
('96f987ac-f782-4627-90f8-815b8f4aa0aa','zh-CN','文艺复兴的作者身份与印刷','比较卡祖拉娜、罗雷与维多利亚的体裁选择及其传播语境。','区分作者身份、体裁标签和传播机构三个层次。','published'),
('96f987ac-f782-4627-90f8-815b8f4aa0aa','en','Authorship and print in the Renaissance','Compare Casulana, Rore, and Victoria through genre choice and circulation context.','Distinguish authorship, genre labels, and circulation institutions.','published'),
('092d687d-3ff0-4f1d-a6ce-084142ed2910','zh-CN','复调与空间','把迪费和维多利亚的复调片段放回礼拜空间与合唱组织中聆听。','用一句话解释空间如何改变复调的可听层次。','published'),
('092d687d-3ff0-4f1d-a6ce-084142ed2910','en','Polyphony and space','Place Dufay and Victoria''s polyphonic excerpts within worship space and choral organization.','Explain in one sentence how space changes audible polyphonic layers.','published'),
('954386a4-3fa3-4ed2-b9b0-8865814db46b','zh-CN','巴洛克圣乐与记忆','从许茨的圣乐中观察文本、低音支点和合唱声部的层次。','指出一个低音支点与一个声部模仿的听觉线索。','published'),
('954386a4-3fa3-4ed2-b9b0-8865814db46b','en','Baroque sacred sound and memory','Observe text, bass support, and choral layers in Schütz''s sacred music.','Identify one bass-support cue and one imitative-voice cue.','published'),
('9e5fa257-da25-47e1-a495-6e194e36f58a','zh-CN','键盘炫技与身体动作','比较吕利舞曲节奏和斯卡拉蒂键盘手势如何组织身体感。','标出一个规则脉动与一个跳跃性音型。','published'),
('9e5fa257-da25-47e1-a495-6e194e36f58a','en','Keyboard virtuosity and physical gesture','Compare Lully''s dance pulse with Scarlatti''s keyboard gestures as bodily organization.','Mark one regular pulse and one leaping figure.','published'),
('0a0cb70d-a51f-4b0e-ad01-5223f7dae15b','zh-CN','感伤主义到古典主义','以C.P.E.巴赫和凯鲁比尼的作品比较句法、情绪与公共体裁。','用三个形容词描述两种句法的差别并说明依据。','published'),
('0a0cb70d-a51f-4b0e-ad01-5223f7dae15b','en','From Empfindsamkeit to Classicism','Compare syntax, affect, and public genres through C. P. E. Bach and Cherubini.','Use three adjectives to describe the syntactic contrast and give evidence.','published'),
('2fb0f925-f34a-4e7f-958e-409fe61757b5','zh-CN','浪漫主义的作者肖像','比较门德尔松、克拉拉·舒曼与布鲁克纳如何在作品中构造公共身份。','区分传记叙事与作品证据，写出一条可核验的观察。','published'),
('2fb0f925-f34a-4e7f-958e-409fe61757b5','en','Romantic composer identity','Compare how Mendelssohn, Clara Schumann, and Bruckner construct public identity through works.','Separate biographical narrative from work evidence in one verifiable observation.','published'),
('58ca1f5f-4d1c-4c84-b348-4f3093826776','zh-CN','交响乐团的扩张','聆听布鲁克纳、穆索尔斯基与施特劳斯的配器层次。','指出一个音色层叠和一个结构性高潮。','published'),
('58ca1f5f-4d1c-4c84-b348-4f3093826776','en','The expanding Romantic orchestra','Listen for orchestral layers in Bruckner, Mussorgsky, and Strauss.','Identify one timbral layer and one structural climax.','published'),
('99a215b1-7b25-450f-8032-46d8c813a438','zh-CN','现代舞台与表现主义','从《莎乐美》和《沃采克》观察和声张力、舞台时间与人物心理。','在片段中标注一个张力累积点，并说明它如何服务戏剧。','published'),
('99a215b1-7b25-450f-8032-46d8c813a438','en','Modern stage and expressionism','Trace harmonic tension, stage time, and character psychology in Salome and Wozzeck.','Annotate one accumulation of tension and explain its dramatic function.','published'),
('e7cd3d25-664d-448f-88d3-782b4d65c8a9','zh-CN','战争、制度与作曲选择','把欣德米特、贝尔格和肖斯塔科维奇放入制度与战争的时间轴。','区分作品年代、首演节点与政治解释的证据等级。','published'),
('e7cd3d25-664d-448f-88d3-782b4d65c8a9','en','War, institutions, and compositional choice','Place Hindemith, Berg, and Shostakovich on a timeline of institutions and war.','Distinguish evidence levels for composition dates, premieres, and political interpretations.','published'),
('8237a552-1c95-40c1-95e2-72a983105f60','zh-CN','人声、磁带与空间','以贝里奥和施托克豪森的作品进入战后电子与音色化听觉。','写出一个关于声音材料而非作曲家意图的听觉判断。','published'),
('8237a552-1c95-40c1-95e2-72a983105f60','en','Voice, tape, and space','Enter postwar electronic and timbral listening through Berio and Stockhausen.','Write one listening judgement about sound material rather than authorial intent.','published')
